        ):
            raise ValueError("plateau statistics must be finite")
        previous = prev_mean
        recent = recent_mean
        change = difference
        if difference <= tolerance:
            stable += 1
        else:
            stable = 0
        if episode is None and e >= min_episodes and stable >= w:
            episode = e

    return {
